const app = document.getElementById('app');
const modalRoot = document.getElementById('modal-root');
const toastRegion = document.getElementById('toast-region');

const icons = {
  grid:'<path d="M4 4h6v6H4zM14 4h6v6h-6zM4 14h6v6H4zM14 14h6v6h-6z"/>', database:'<ellipse cx="12" cy="5" rx="8" ry="3"/><path d="M4 5v7c0 1.7 3.6 3 8 3s8-1.3 8-3V5M4 12v7c0 1.7 3.6 3 8 3s8-1.3 8-3v-7"/>', flask:'<path d="M9 3v6l-5.9 9.2A1.2 1.2 0 0 0 4.1 20h15.8a1.2 1.2 0 0 0 1-1.8L15 9V3M7 3h10M8 15h8"/>', chart:'<path d="M4 19V5M4 19h16"/><path d="m7 15 3-4 3 2 5-7"/>', tree:'<circle cx="12" cy="4" r="2.4"/><circle cx="6" cy="12" r="2.4"/><circle cx="18" cy="12" r="2.4"/><circle cx="4" cy="20" r="2.4"/><circle cx="10" cy="20" r="2.4"/><circle cx="14" cy="20" r="2.4"/><circle cx="20" cy="20" r="2.4"/><path d="M12 6.5V9M12 9 6 9.5M12 9l6 .5M6 14.5V17M6 17h-2M6 17h4M18 14.5V17M18 17h-4M18 17h2"/>', plus:'<path d="M12 5v14M5 12h14"/>', arrow:'<path d="M5 12h14M13 6l6 6-6 6"/>', close:'<path d="m6 6 12 12M18 6 6 18"/>', check:'<path d="m5 12 4 4L19 6"/>', clock:'<circle cx="12" cy="12" r="8.5"/><path d="M12 7v5l3 2"/>', info:'<circle cx="12" cy="12" r="8.5"/><path d="M12 10.5v5M12 7.5h.01"/>', spark:'<path d="m12 3 1.7 5.3L19 10l-5.3 1.7L12 17l-1.7-5.3L5 10l5.3-1.7L12 3Z"/>', search:'<circle cx="10.8" cy="10.8" r="6.8"/><path d="m16 16 4.5 4.5"/>', settings:'<path d="M12 8.8a3.2 3.2 0 1 0 0 6.4 3.2 3.2 0 0 0 0-6.4Z"/><path d="m19.4 13.5 1.2 1-.1 1.3-1.8 1.7-1.4-.3-1.1.6-.4 1.4-2.3.4-1-1.1-1.2-.2-1 1-2.3-.8-.3-1.4-1-.8-1.4.1L4 14.5l.6-1.3-.3-1.2-1.1-.8.5-2.3 1.4-.4.5-1.1-.5-1.4 1.7-1.7 1.4.4 1-.6.5-1.4 2.3-.3 1 1.1 1.2.2 1-1 2.3.8.3 1.4 1 .8 1.4-.1 1.4 1.7-.6 1.3.3 1.2 1.1.8-.5 2.3-1.4.4-.5 1.1Z"/>', upload:'<path d="M12 16V4M7 9l5-5 5 5M5 19h14"/>', trash:'<path d="M4 7h16M10 11v6M14 11v6M6 7l1 13h10l1-13M9 7V4h6v3"/>', edit:'<path d="m4 16 10-10 4 4L8 20H4zM13 7l4 4"/>', logout:'<path d="M10 17l5-5-5-5M15 12H3M21 19V5a2 2 0 0 0-2-2h-5"/>', external:'<path d="M14 5h5v5M19 5l-8 8"/><path d="M18 13v5a1 1 0 0 1-1 1H6a1 1 0 0 1-1-1V7a1 1 0 0 1 1-1h5"/>'
};
const icon = (name, size=16) => `<svg aria-hidden="true" width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round">${icons[name] || icons.info}</svg>`;
const esc = (value) => String(value ?? '').replace(/[&<>'"]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const pct = value => `${Math.round(Number(value || 0) * 100)}%`;

const state = {
  user: null, health: {status:'unknown', database:'unknown'}, view: 'landing', workspaceTab: 'overview', datasets: [], experiments: [], selectedDatasetId: null,
  search: '',   selectedComparison: [], comparisonMode: 'raw', selectedSampleId: '', preview: null, modal: null, authMode: 'login', busy: false, training: false, automlRunning: false,
  preprocessing: { target:'', features:[], missing:'Median imputation', encoding:'One-hot encoding', scaling:'Standard scaler', duplicates:'Keep first row', imbalance:'Balanced class weights', split:80 },
  modelType:'Decision Tree', modelConfig:{ criterion:'gini', maxDepth:'5', minSplit:'2', minLeaf:'1', classWeight:'Balanced' },
  rfConfig:{ estimators:'100', maxDepth:'8', maxFeatures:'sqrt', minSplit:'2', classWeight:'Balanced' },
  automl:{ mode:'Controlled', timeBudget:30, metric:'F1 score', validation:'Stratified 5-fold' },
  toasts:[]
};

async function api(path, options={}) {
  const response = await fetch(path, { credentials:'include', ...options });
  const type = response.headers.get('content-type') || '';
  const data = type.includes('application/json') ? await response.json() : await response.text();
  if (!response.ok) throw new Error(data?.detail || data || `Request failed (${response.status})`);
  return data;
}
function notify(title, message, kind='info') {
  const id = `toast-${Date.now()}-${Math.random()}`;
  state.toasts.push({id,title,message,kind}); renderToasts();
  setTimeout(() => { state.toasts = state.toasts.filter(item => item.id !== id); renderToasts(); }, 4800);
}
function renderToasts() { toastRegion.innerHTML = state.toasts.map(t => `<div class="toast ${t.kind}"><div class="toast-icon">${icon(t.kind === 'success' ? 'check' : 'info', 14)}</div><div><strong>${esc(t.title)}</strong><p>${esc(t.message)}</p></div><button class="icon-btn" data-action="dismiss-toast" data-id="${t.id}">${icon('close',13)}</button></div>`).join(''); }
function selectedDataset() { return state.datasets.find(item => item.id === state.selectedDatasetId) || state.datasets[0]; }
function completedExperiment(item) { return item?.status === 'completed' && item.metrics && typeof item.metrics === 'object'; }
function selectedExperiments() { return state.experiments.filter(item => state.selectedComparison.includes(item.id) && completedExperiment(item)); }
function datasetExperiments() { const d = selectedDataset(); return d ? state.experiments.filter(item => item.dataset_id === d.id && completedExperiment(item)) : []; }
function comparisonSignature(experiment) {
  const preprocessing = experiment?.parameters?.preprocessing || {};
  return JSON.stringify({
    datasetVersion: experiment?.dataset_version_id || null,
    target: preprocessing.target || null,
    features: Array.isArray(preprocessing.features) ? preprocessing.features : [],
    split: preprocessing.split ?? null,
    missing: preprocessing.missing || null,
    encoding: preprocessing.encoding || null,
    scaling: preprocessing.scaling || null,
    duplicates: preprocessing.duplicates || null,
    imbalance: preprocessing.imbalance || null,
    average: experiment?.metrics?.evaluation?.average || null,
    validation: experiment?.metrics?.evaluation?.validation || null
  });
}
function comparisonWarning(experiments) {
  if (experiments.length < 2) return '';
  const signatures = new Set(experiments.map(comparisonSignature));
  return signatures.size > 1 ? '<div class="notice notice-warning">These runs use different dataset versions or evaluation settings. Compare them descriptively; do not treat the ranking as a controlled model comparison.</div>' : '';
}
function setView(view) { state.view = view; state.workspaceTab = 'overview'; render(); window.scrollTo({top:0,behavior:'smooth'}); }
function dbStatus() { const ready=state.health?.database==='connected'; return ready ? {label:'DATABASE CONNECTED',message:'Your datasets and experiments are persisted in your private workspace.',online:'online'} : {label:'DATABASE UNAVAILABLE',message:state.health?.detail || 'Configure PostgreSQL to use authenticated persistence.',online:'offline'}; }
async function refreshHealth() { try { state.health=await api('/api/health'); } catch(error) { state.health={status:'degraded',database:'unavailable',detail:error.message}; } }
async function refreshData() {
  if (!state.user) return;
  state.datasets = await api('/api/datasets');
  state.experiments = await api('/api/experiments');
  if (!state.selectedDatasetId && state.datasets[0]) state.selectedDatasetId = state.datasets[0].id;
  if (state.selectedDatasetId && !state.datasets.some(d => d.id === state.selectedDatasetId)) state.selectedDatasetId = state.datasets[0]?.id || null;
}
async function openWorkspace(id=state.selectedDatasetId, tab='overview') {
  state.selectedDatasetId = id; state.workspaceTab = tab; state.view = 'workspace'; state.preview = null; render();
  const d = selectedDataset();
  if (d?.version_id) { try { state.preview = await api(`/api/datasets/${d.id}/versions/${d.version_id}/preview`); state.preprocessing.target = d.target_column || state.preview.target_candidates[0] || ''; state.preprocessing.features = state.preview.columns.filter(c => c.name !== state.preprocessing.target).map(c => c.name); } catch (error) { notify('Could not load preview', error.message, 'warning'); } }
  render(); window.scrollTo({top:0,behavior:'smooth'});
}
function render() { app.innerHTML = state.user ? shell() : landing(); renderToasts(); if (state.modal) renderModal(); else modalRoot.innerHTML = ''; requestAnimationFrame(renderAnalyticsCharts); }

function landing() {
  return `<div class="landing"><header class="landing-header"><div class="wordmark"><span class="wordmark-mark"></span><span>TreeLab</span><span class="wordmark-sub">private ML workspace</span></div><div class="landing-header-actions"><button class="btn btn-secondary btn-sm" data-action="open-auth" data-mode="login">Log in ${icon('arrow',13)}</button><button class="btn btn-primary btn-sm" data-action="open-auth" data-mode="register">Create account ${icon('plus',13)}</button></div></header><main><section class="landing-hero"><div><span class="eyebrow">The visual lab for model thinking</span><h1 class="hero-title">Start with a dataset.<br/>End with <span class="accent">evidence.</span></h1><p class="hero-copy">TreeLab turns the machine-learning workflow into a private, durable workspace — from CSV ingestion to real model evaluation and explainability.</p><div class="hero-actions"><button class="btn btn-primary" data-action="open-auth" data-mode="register">Create your workspace ${icon('arrow',15)}</button><button class="btn btn-ghost" data-action="scroll-workflow">See how it works ${icon('arrow',14)}</button></div><div class="hero-note"><span class="dot"></span> PostgreSQL-backed · scikit-learn + FLAML</div></div><div class="product-preview"><div class="preview-topbar"><div class="preview-dots"><span></span><span></span><span></span></div><span class="mono">workspace / customer-churn / overview</span><span>${icon('database',15)}</span></div><div class="preview-body"><div class="preview-rail"><div class="preview-rail-brand"></div><div class="preview-rail-line active"></div><div class="preview-rail-line"></div><div class="preview-rail-line"></div><div class="preview-rail-line"></div><div class="preview-rail-line"></div></div><div class="preview-canvas"><div class="preview-caption"><div><span>DATABASE WORKSPACE</span><strong>Customer Churn Dataset</strong></div><span class="tag green">${icon('check',10)} ready</span></div><div class="preview-grid"><div class="preview-stat"><b>12</b><small>rows in demo</small></div><div class="preview-stat"><b>6</b><small>features</small></div><div class="preview-stat"><b>real</b><small>training path</small></div></div><div class="preview-chart"><span class="preview-badge">POSTGRESQL</span><svg viewBox="0 0 500 190" preserveAspectRatio="none"><path d="M0 150 C48 140,65 114,103 126 S155 105,185 117 S224 81,259 95 S303 64,341 76 S393 45,423 61 S467 24,500 30" fill="none" stroke="#38bdf8" stroke-width="3"/><path d="M0 150 C48 140,65 114,103 126 S155 105,185 117 S224 81,259 95 S303 64,341 76 S393 45,423 61 S467 24,500 30 V190 H0Z" fill="#38bdf8" opacity=".14"/></svg></div></div></div></div></section><section class="landing-section" id="workflow"><div class="section-heading"><div><span class="section-kicker">One workflow, fully visible</span><h2 class="section-title">A lab bench for every decision.</h2></div><p class="section-desc">Upload data, inspect its shape, configure preprocessing, run a real estimator, and trace the result.</p></div><div class="workflow-grid"><div class="workflow-step"><span class="step-no">01 / INPUT</span><h3>Upload dataset</h3><p>Parse and persist CSVs with schema, target candidates, previews, and immutable versions.</p></div><div class="workflow-step"><span class="step-no">02 / UNDERSTAND</span><h3>Explore the signal</h3><p>See distributions, missingness, correlations, and target behavior before fitting.</p></div><div class="workflow-step"><span class="step-no">03 / EXPERIMENT</span><h3>Train and compare</h3><p>Use scikit-learn Decision Trees, Random Forests, or FLAML AutoML with persisted results.</p></div><div class="workflow-step"><span class="step-no">04 / EXPLAIN</span><h3>Make it legible</h3><p>Review feature importance, permutation importance, probabilities, and holdout metrics.</p></div></div></section></main><footer class="landing-footer"><div style="max-width:1240px;margin:auto;display:flex;justify-content:space-between;gap:20px;flex-wrap:wrap"><span>TreeLab / private experimentation workspace</span><span class="mono">Your datasets stay in your workspace</span></div></footer></div>`;
}
function shell() {
  const title = state.view === 'dashboard' ? 'Dashboard' : state.view === 'datasets' ? 'My Datasets' : selectedDataset()?.name || 'Workspace';
  return `<div class="app-shell"><aside class="sidebar"><div class="sidebar-brand"><button class="wordmark" style="border:0;background:transparent;color:inherit;padding:0" data-action="nav" data-view="dashboard"><span class="wordmark-mark"></span><span>TreeLab</span></button></div><nav class="sidebar-nav"><span class="nav-label">Workspace</span>${nav('dashboard','Dashboard','grid')}${nav('datasets','My Datasets','database')}<span class="nav-label">Labs</span>${labNav('explorer','Data Explorer','chart')}${labNav('preprocess','Preprocessing Studio','settings')}${labNav('models','Model Laboratory','tree')}${labNav('automl','AutoML Laboratory','spark')}<span class="nav-label">Review</span>${labNav('compare','Model Comparison','chart')}${labNav('explain','Explainability','eye')}${labNav('history','Experiment History','clock')}</nav><div class="sidebar-bottom"><div class="simulation-note" style="border-color:rgba(105,225,181,.25)"><b>${dbStatus().label}</b><p>${esc(dbStatus().message)}</p></div></div></aside><div class="main-shell"><header class="topbar"><div class="breadcrumbs"><span>TreeLab</span><span class="breadcrumb-sep">/</span><strong>${esc(title)}</strong>${state.view === 'workspace' ? `<span class="breadcrumb-sep">/</span><span>${esc(state.workspaceTab)}</span>` : ''}</div><div class="topbar-actions"><span class="system-status"><span class="dot"></span>${esc(state.user.role)} / ${esc(dbStatus().online)}</span><button class="icon-btn" data-action="logout" aria-label="Log out">${icon('logout',15)}</button><div class="profile-chip"><span>${esc(state.user.name)}</span><span class="avatar">${esc(state.user.name.split(' ').map(v=>v[0]).join('').slice(0,2).toUpperCase())}</span></div></div></header>${state.view === 'dashboard' ? dashboard() : state.view === 'datasets' ? datasetsPage() : workspacePage()}</div></div>`;
}
function nav(view,label,ico) { return `<button class="nav-item ${state.view === view ? 'active' : ''}" data-action="nav" data-view="${view}">${icon(ico,16)}<span>${label}</span></button>`; }
function labNav(tab,label,ico) { return `<button class="nav-item ${state.view === 'workspace' && state.workspaceTab === tab ? 'active' : ''}" data-action="workspace-tab" data-tab="${tab}">${icon(ico,16)}<span>${label}</span></button>`; }
function dashboard() {
  const best = state.experiments.length ? Math.max(...state.experiments.map(e => Number(e.metrics?.accuracy || 0))) : 0;
  return `<main class="page"><div class="page-heading"><div><span class="section-kicker">Overview / private workspace</span><h1>Good to see you, ${esc(state.user.name.split(' ')[0])}.</h1><p>Your data, models, and evidence stay scoped to this account.</p></div><div class="page-heading-actions"><button class="btn btn-ghost" data-action="nav" data-view="datasets">${icon('database',14)} Browse datasets</button><button class="btn btn-primary" data-action="open-upload">${icon('plus',14)} Add dataset</button></div></div><div class="metric-grid"><div class="metric-card"><div class="metric-label"><span>Your datasets</span>${icon('database',14)}</div><div class="metric-value">${String(state.datasets.filter(d=>!d.is_demo).length).padStart(2,'0')}</div><span class="metric-change">private records</span></div><div class="metric-card violet"><div class="metric-label"><span>Experiments</span>${icon('flask',14)}</div><div class="metric-value">${String(state.experiments.length).padStart(2,'0')}</div><span class="metric-change">persisted runs</span></div><div class="metric-card green"><div class="metric-label"><span>Models</span>${icon('tree',14)}</div><div class="metric-value">${String(state.experiments.filter(e=>e.status==='completed').length).padStart(2,'0')}</div><span class="metric-change">ready to review</span></div><div class="metric-card amber"><div class="metric-label"><span>Best accuracy</span>${icon('chart',14)}</div><div class="metric-value">${best ? pct(best) : '—'}</div><span class="metric-change muted">holdout metric</span></div></div><div class="dashboard-grid"><section class="panel"><div class="panel-header"><div><h2 class="panel-title">Experiment performance</h2><p class="panel-subtitle">Persisted holdout accuracy across your runs</p></div><span class="tag blue">REAL RESULTS</span></div>${metricBars(state.experiments.slice(0,6).map(e=>({label:e.model_type,value:e.metrics?.accuracy,color:'cyan'})))}</section><section class="panel"><div class="panel-header"><div><h2 class="panel-title">Recent activity</h2><p class="panel-subtitle">Your latest data and model work</p></div><button class="icon-btn" data-action="workspace-tab" data-tab="history">${icon('external',14)}</button></div>${state.experiments.slice(0,4).map(e=>`<div class="activity-row"><span class="activity-icon">${icon(e.status==='completed'?'check':'clock',14)}</span><div><strong>${esc(e.model_type)}</strong><span>${esc(state.datasets.find(d=>d.id===e.dataset_id)?.name || 'Dataset')} · ${pct(e.metrics?.accuracy || 0)} accuracy</span></div><span class="activity-time">${new Date(e.created_at || Date.now()).toLocaleDateString()}</span></div>`).join('') || empty('No experiments yet','Train a model from a dataset workspace.')}</section></div><section class="panel"><div class="panel-header"><div><h2 class="panel-title">Recent datasets</h2><p class="panel-subtitle">Open a dataset to continue your workflow</p></div><button class="btn btn-ghost btn-sm" data-action="nav" data-view="datasets">View all ${icon('arrow',12)}</button></div><div class="dataset-mini-list">${state.datasets.map(d=>`<button class="dataset-mini" data-action="open-dataset" data-id="${d.id}" style="text-align:left;color:inherit"><span class="dataset-icon">${icon('database',15)}</span><strong>${esc(d.name)}</strong><small>${d.row_count.toLocaleString()} rows · ${d.column_count} columns${d.is_demo?' · demo fixture':''}</small></button>`).join('') || empty('No datasets available','Upload your first CSV to begin.')}</div></section></main>`;
}
function datasetsPage() {
  const filtered = state.datasets.filter(d => !state.search || `${d.name} ${d.description} ${d.target_column || ''}`.toLowerCase().includes(state.search.toLowerCase()));
  return `<main class="page"><div class="page-heading"><div><span class="section-kicker">Workspace / datasets</span><h1>My Datasets</h1><p>Inputs, versions, targets, and schema stay close at hand.</p></div><div class="page-heading-actions"><span class="tag blue">${state.datasets.filter(d=>!d.is_demo).length} PRIVATE DATASETS</span><button class="btn btn-primary" data-action="open-upload">${icon('upload',14)} Upload CSV</button></div></div><div class="toolbar"><div class="toolbar-left"><label class="search-wrap">${icon('search',14)}<input id="dataset-search" value="${esc(state.search)}" placeholder="Search datasets, targets, or descriptions" /></label></div><div class="toolbar-right"><span class="tag blue">${state.datasets.length} available to you</span></div></div>${filtered.length ? `<div class="dataset-table"><div class="table-head"><span>Dataset</span><span>Task</span><span>Rows</span><span>Columns</span><span>Version</span><span></span></div>${filtered.map(d=>`<div class="dataset-row"><div class="dataset-name"><span class="dataset-icon" style="margin:0;flex:0 0 auto">${icon('database',15)}</span><div><strong>${esc(d.name)} ${d.is_demo?'<span class="tag amber">DEMO</span>':''}</strong><span>Target: <span class="mono">${esc(d.target_column || 'not set')}</span> · ${esc(d.description || 'No description')}</span></div></div><span class="dataset-type">${esc(d.task_type)}</span><span class="table-cell mono">${d.row_count.toLocaleString()}</span><span class="table-cell mono">${d.column_count}</span><span class="table-cell">v${d.version_number || 0}</span><div class="row-actions"><button class="icon-btn" data-action="open-dataset" data-id="${d.id}" aria-label="Open dataset">${icon('arrow',14)}</button>${d.is_demo?'':`<button class="icon-btn" data-action="edit-dataset" data-id="${d.id}" aria-label="Edit dataset">${icon('edit',14)}</button><button class="icon-btn" data-action="delete-dataset" data-id="${d.id}" aria-label="Delete dataset">${icon('trash',14)}</button>`}</div></div>`).join('')}</div>` : empty('No datasets match that query','Clear the search or upload a new CSV.')}</main>`;
}
function workspacePage() {
  const d = selectedDataset();
  if (!d) return `<main class="page">${empty('No dataset selected','Open the dataset library and choose a workspace.')}</main>`;
  const tabs = [['overview','Overview'],['explorer','Data Explorer'],['preprocess','Preprocessing Studio'],['models','Model Laboratory'],['automl','AutoML Laboratory'],['compare','Model Comparison'],['explain','Explainability Studio'],['history','Experiment History']];
  return `<main class="page"><section class="workspace-heading"><div class="workspace-identity"><span class="dataset-icon">${icon('database',18)}</span><div><h1>${esc(d.name)}</h1><p>${d.row_count.toLocaleString()} rows · ${d.column_count} columns · target: ${esc(d.target_column || 'not set')} · ${d.is_demo?'public demo fixture':'private dataset'}</p></div></div><div class="workspace-actions"><button class="btn btn-ghost btn-sm" data-action="nav" data-view="datasets">${icon('database',13)} Switch dataset</button>${d.is_demo?'':`<button class="btn btn-secondary btn-sm" data-action="open-version-upload">${icon('upload',13)} New version</button>`}</div></section><nav class="workspace-tabs">${tabs.map(([id,label])=>`<button class="tab-btn ${state.workspaceTab===id?'active':''}" data-action="workspace-tab" data-tab="${id}">${label}${id==='history'?`<span class="tab-badge">${datasetExperiments().length}</span>`:''}</button>`).join('')}</nav>${renderWorkspaceContent(d)}</main>`;
}
function renderWorkspaceContent(d) { return ({overview:overviewTab,explorer:explorerTab,preprocess:preprocessTab,models:modelsTab,automl:automlTab,compare:compareTab,explain:explainTab,history:historyTab}[state.workspaceTab] || overviewTab)(d); }
function overviewTab(d) { const exps=datasetExperiments(); const best=exps.length?Math.max(...exps.map(e=>e.metrics?.accuracy||0)):0; return `<div class="workspace-grid"><div><section class="panel panel-accent"><div class="panel-header"><div><span class="section-kicker">Workspace overview</span><h2 class="section-title" style="font-size:23px;margin-top:8px">The shape of <span style="color:var(--cyan)">${esc(d.name)}</span>.</h2><p class="panel-subtitle" style="font-size:11px;max-width:460px;line-height:1.65">${esc(d.description || 'Explore the input, make preprocessing choices visible, then run a controlled experiment.')}</p></div><span class="tag green">PERSISTED</span></div><div class="metric-row"><div class="mini-metric"><span>Rows</span><b>${d.row_count.toLocaleString()}</b></div><div class="mini-metric"><span>Columns</span><b>${d.column_count}</b></div><div class="mini-metric"><span>Versions</span><b>${d.version_number || 0}</b></div><div class="mini-metric"><span>Best accuracy</span><b>${best?pct(best):'—'}</b></div></div></section><section class="section-block panel"><div class="panel-header"><div><h2 class="panel-title">Performance overview</h2><p class="panel-subtitle">Real validation metrics from this dataset</p></div><button class="btn btn-ghost btn-sm" data-action="workspace-tab" data-tab="compare">Compare ${icon('arrow',12)}</button></div>${metricBars(exps.map(e=>({label:e.model_type,value:e.metrics?.accuracy,color:'cyan'})))}</section></div><aside><section class="panel panel-accent violet"><div class="panel-header"><div><h2 class="panel-title">Recommended next step</h2><p class="panel-subtitle">Based on the current workspace state</p></div>${icon('spark',15)}</div><h3 style="margin:4px 0 7px;font-size:16px">Inspect the feature signal</h3><p style="margin:0 0 16px;color:var(--muted);font-size:11px;line-height:1.65">Open Data Explorer to review schema and missingness before choosing preprocessing.</p><button class="btn btn-violet btn-sm" data-action="workspace-tab" data-tab="explorer">Open Data Explorer ${icon('arrow',12)}</button></section><section class="section-block panel"><div class="panel-header"><div><h2 class="panel-title">Workspace map</h2><p class="panel-subtitle">A contextual path through the lab</p></div></div><div class="activity-list"><div class="activity-row"><span class="activity-icon">01</span><div><strong>Understand</strong><span>Explorer + schema</span></div><span class="tag blue">NOW</span></div><div class="activity-row"><span class="activity-icon">02</span><div><strong>Prepare</strong><span>Preprocessing studio</span></div><span class="activity-time">next</span></div><div class="activity-row"><span class="activity-icon">03</span><div><strong>Experiment</strong><span>Models + AutoML</span></div><span class="activity-time">later</span></div><div class="activity-row"><span class="activity-icon">04</span><div><strong>Explain</strong><span>Comparison + importance</span></div><span class="activity-time">later</span></div></div></section></aside></div>`; }
function explorerTab(d) { const p=state.preview; return `<div class="workspace-grid"><div><section class="panel"><div class="panel-header"><div><span class="section-kicker">01 / inspect</span><h2 class="panel-title" style="margin-top:8px">Dataset preview</h2><p class="panel-subtitle">Live rows from the persisted active version</p></div><span class="tag blue">${p?'SCHEMA READY':'LOADING'}</span></div>${p?`<div class="data-preview"><table><thead><tr>${p.columns.map(c=>`<th>${esc(c.name)}<br/><span class="type-chip">${c.name===state.preprocessing.target?'target':esc(c.kind)}</span></th>`).join('')}</tr></thead><tbody>${p.preview.map(row=>`<tr>${p.columns.map(c=>`<td>${esc(row[c.name])}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`:'<div class="loading-state">Loading persisted preview…</div>'}</section><section class="section-block panel"><div class="panel-header"><div><h2 class="panel-title">Numeric signal</h2><p class="panel-subtitle">A compact profile of missingness and cardinality</p></div></div>${p?metricBars(p.columns.slice(0,10).map(c=>({label:c.name,value:Math.min(1,(c.unique||0)/Math.max(1,p.row_count)),color:c.nullable?'amber':'cyan',suffix:`${c.unique} unique`}))):''}</section></div><aside><section class="panel"><div class="panel-header"><div><h2 class="panel-title">Column profile</h2><p class="panel-subtitle">Types, cardinality, missingness</p></div>${icon('info',15)}</div><div class="schema-list">${p?p.columns.map(c=>`<div class="schema-row"><div><strong>${esc(c.name)}</strong><small>${esc(c.dtype)} · ${c.missing} missing</small></div><div style="text-align:right"><span class="tag ${c.name===state.preprocessing.target?'violet':c.kind==='categorical'?'amber':'blue'}">${c.name===state.preprocessing.target?'target':c.kind}</span><small style="display:block;margin-top:4px;color:var(--muted);font-family:var(--mono);font-size:8px">${c.unique} unique</small></div></div>`).join(''):''}</div></section><section class="section-block panel panel-accent amber"><div class="panel-header"><div><h2 class="panel-title">Target distribution</h2><p class="panel-subtitle">Class balance before training</p></div><span class="tag amber">CHECK BALANCE</span></div>${p?`<p style="color:var(--muted);font-size:11px;line-height:1.7">${esc(state.preprocessing.target || d.target_column || 'Choose a target')} is profiled from the active version. Train/test stratification is applied when every class has at least two rows.</p>`:''}</section></aside></div>`; }
function preprocessTab(d) { const columns=(state.preview?.columns||[]).map(c=>c.name); const features=columns.filter(c=>c!==state.preprocessing.target); return `<div class="workspace-grid"><section class="panel"><div class="panel-header"><div><span class="section-kicker">02 / prepare</span><h2 class="panel-title" style="margin-top:8px">Preprocessing Studio</h2><p class="panel-subtitle">These choices are stored with every experiment.</p></div><span class="tag blue">READY TO TRAIN</span></div><div class="form-grid"><div class="field"><label>Target selection</label><select class="field-select" data-setting="preprocessing.target">${columns.map(c=>`<option ${state.preprocessing.target===c?'selected':''}>${esc(c)}</option>`).join('')}</select></div><div class="field"><label>Missing-value handling</label><select class="field-select" data-setting="preprocessing.missing">${['Median imputation','Mean imputation','Drop rows','Flag as feature'].map(v=>`<option ${state.preprocessing.missing===v?'selected':''}>${v}</option>`).join('')}</select></div><div class="field"><label>Categorical encoding</label><select class="field-select" data-setting="preprocessing.encoding">${['One-hot encoding','Ordinal encoding'].map(v=>`<option ${state.preprocessing.encoding===v?'selected':''}>${v}</option>`).join('')}</select></div><div class="field"><label>Feature scaling</label><select class="field-select" data-setting="preprocessing.scaling">${['Standard scaler','Robust scaler','Min-max scaler','No scaling'].map(v=>`<option ${state.preprocessing.scaling===v?'selected':''}>${v}</option>`).join('')}</select></div><div class="field"><label>Duplicate handling</label><select class="field-select" data-setting="preprocessing.duplicates">${['Keep first row','Drop duplicates'].map(v=>`<option ${state.preprocessing.duplicates===v?'selected':''}>${v}</option>`).join('')}</select></div><div class="field"><label>Class imbalance strategy</label><select class="field-select" data-setting="preprocessing.imbalance">${['Balanced class weights','No adjustment'].map(v=>`<option ${state.preprocessing.imbalance===v?'selected':''}>${v}</option>`).join('')}</select></div><div class="field full"><label>Feature selection <span class="field-help">${state.preprocessing.features.length} selected</span></label><div class="check-grid">${features.map(c=>`<label class="check-chip"><input type="checkbox" data-feature="${esc(c)}" ${state.preprocessing.features.includes(c)?'checked':''}/>${esc(c)}</label>`).join('')}</div></div><div class="field full"><label>Train / test split <span class="range-value">${state.preprocessing.split}% / ${100-state.preprocessing.split}%</span></label><div class="range-line"><span class="mono">train</span><input type="range" min="60" max="90" step="5" value="${state.preprocessing.split}" data-setting="preprocessing.split"/><span class="mono">test</span></div></div></div><div style="display:flex;justify-content:flex-end;gap:8px;margin-top:22px;padding-top:16px;border-top:1px solid var(--line)"><button class="btn btn-primary btn-sm" data-action="workspace-tab" data-tab="models">Continue to model lab ${icon('arrow',13)}</button></div></section><aside><section class="panel panel-accent"><div class="panel-header"><div><h2 class="panel-title">Pipeline preview</h2><p class="panel-subtitle">What the real trainer will run</p></div><span class="tag green">VERSIONED</span></div><div class="pipeline"><div class="pipeline-node"><strong>Input</strong><span>${esc(d.name)}</span></div><span class="pipeline-arrow">→</span><div class="pipeline-node"><strong>Clean</strong><span>${esc(state.preprocessing.missing.split(' ')[0])}</span></div><span class="pipeline-arrow">→</span><div class="pipeline-node"><strong>Encode</strong><span>${esc(state.preprocessing.encoding.split(' ')[0])}</span></div><span class="pipeline-arrow">→</span><div class="pipeline-node"><strong>Fit</strong><span>scikit-learn</span></div></div><div style="padding-top:14px;border-top:1px solid var(--line)"><div class="stat-row"><span>Target</span><b>${esc(state.preprocessing.target)}</b><b>${state.preprocessing.split}% train</b></div><div class="stat-row"><span>Features</span><b>${state.preprocessing.features.length}</b><b>${100-state.preprocessing.split}% test</b></div></div></section></aside></div>`; }
function modelsTab(d) { const tree=state.modelType==='Decision Tree'; return `<div class="workspace-grid"><section class="panel"><div class="panel-header"><div><span class="section-kicker">03 / experiment</span><h2 class="panel-title" style="margin-top:8px">Model Laboratory</h2><p class="panel-subtitle">Fit a real estimator against the active dataset version.</p></div><div class="model-tabs"><button class="model-tab ${tree?'active':''}" data-action="set-model" data-model="Decision Tree">Decision Tree</button><button class="model-tab ${!tree?'active':''}" data-action="set-model" data-model="Random Forest">Random Forest</button></div></div><div class="form-grid">${tree?`<div class="field"><label>Criterion</label><select class="field-select" data-setting="model.criterion">${['gini','entropy'].map(v=>`<option ${state.modelConfig.criterion===v?'selected':''}>${v}</option>`).join('')}</select></div><div class="field"><label>Maximum depth</label><select class="field-select" data-setting="model.maxDepth">${['3','5','8','None'].map(v=>`<option ${state.modelConfig.maxDepth===v?'selected':''}>${v}</option>`).join('')}</select></div><div class="field"><label>Minimum samples split</label><select class="field-select" data-setting="model.minSplit">${['2','5','10','20'].map(v=>`<option ${state.modelConfig.minSplit===v?'selected':''}>${v}</option>`).join('')}</select></div><div class="field"><label>Minimum samples leaf</label><select class="field-select" data-setting="model.minLeaf">${['1','2','4','8'].map(v=>`<option ${state.modelConfig.minLeaf===v?'selected':''}>${v}</option>`).join('')}</select></div><div class="field"><label>Class weight</label><select class="field-select" data-setting="model.classWeight">${['Balanced','None'].map(v=>`<option ${state.modelConfig.classWeight===v?'selected':''}>${v}</option>`).join('')}</select></div>`:`<div class="field"><label>Number of estimators</label><select class="field-select" data-setting="rf.estimators">${['50','100','200','400'].map(v=>`<option ${state.rfConfig.estimators===v?'selected':''}>${v}</option>`).join('')}</select></div><div class="field"><label>Maximum depth</label><select class="field-select" data-setting="rf.maxDepth">${['5','8','12','None'].map(v=>`<option ${state.rfConfig.maxDepth===v?'selected':''}>${v}</option>`).join('')}</select></div><div class="field"><label>Maximum features</label><select class="field-select" data-setting="rf.maxFeatures">${['sqrt','log2','None'].map(v=>`<option ${state.rfConfig.maxFeatures===v?'selected':''}>${v}</option>`).join('')}</select></div><div class="field"><label>Minimum samples split</label><select class="field-select" data-setting="rf.minSplit">${['2','5','10','20'].map(v=>`<option ${state.rfConfig.minSplit===v?'selected':''}>${v}</option>`).join('')}</select></div><div class="field"><label>Class weight</label><select class="field-select" data-setting="rf.classWeight">${['Balanced','None'].map(v=>`<option ${state.rfConfig.classWeight===v?'selected':''}>${v}</option>`).join('')}</select></div>`}</div><div style="display:flex;justify-content:flex-end;margin-top:18px"><button class="btn btn-primary" data-action="train-model" ${state.training?'disabled':''}>${state.training?icon('clock',14):icon('flask',14)} ${state.training?'Training…':'Train model'}</button></div></section><aside><section class="panel panel-accent green"><div class="panel-header"><div><h2 class="panel-title">Latest result</h2><p class="panel-subtitle">Persisted holdout metrics</p></div><span class="tag green">${state.training?'RUNNING':'REAL RESULT'}</span></div>${state.training?'<div class="loading-state">Preparing split · fitting estimator · scoring holdout…</div>':latestResultHtml(d)}</section><section class="section-block panel"><div class="panel-header"><div><h2 class="panel-title">Configuration snapshot</h2><p class="panel-subtitle">Recorded with the next experiment</p></div></div><div class="stat-list"><div class="stat-row"><span>Target</span><b>${esc(state.preprocessing.target)}</b><b>${state.preprocessing.split}% train</b></div><div class="stat-row"><span>Features</span><b>${state.preprocessing.features.length}</b><b>${esc(state.preprocessing.scaling)}</b></div></div></section></aside></div>`; }
function latestResultHtml(d) { const e=datasetExperiments()[0]; return e?`<div class="metric-row"><div class="mini-metric"><span>Accuracy</span><b>${pct(e.metrics.accuracy)}</b></div><div class="mini-metric"><span>Precision</span><b>${pct(e.metrics.precision)}</b></div><div class="mini-metric"><span>Recall</span><b>${pct(e.metrics.recall)}</b></div><div class="mini-metric"><span>F1</span><b>${pct(e.metrics.f1)}</b></div></div><div style="margin-top:15px;padding-top:14px;border-top:1px solid var(--line);display:flex;justify-content:space-between;color:var(--muted);font-size:10px"><span>${esc(e.model_type)}</span><span class="mono">${e.duration_ms}ms</span></div>`:empty('Metrics will appear here','Run a model to persist a real evaluation summary.'); }
  function automlTab(d) { return `<div class="workspace-grid"><section class="panel panel-accent violet"><div class="panel-header"><div><span class="section-kicker" style="color:#c5b4fc">04 / search</span><h2 class="panel-title" style="margin-top:8px">AutoML Laboratory</h2><p class="panel-subtitle">FLAML searches a real estimator space under an explicit time budget.</p></div><span class="tag violet">FLAML</span></div><div class="model-tabs" style="margin-bottom:18px"><button class="model-tab ${state.automl.mode==='Controlled'?'active':''}" data-action="set-automl-mode" data-mode="Controlled">Controlled Mode</button><button class="model-tab ${state.automl.mode==='Extended'?'active':''}" data-action="set-automl-mode" data-mode="Extended">Extended Mode</button></div><div class="form-grid"><div class="field"><label>Time budget (seconds)<span class="field-help">Maximum 90 seconds</span></label><input class="field-select" type="number" min="1" max="90" value="${state.automl.timeBudget}" data-setting="automl.timeBudget"/></div><div class="field"><label>Optimization metric</label><select class="field-select" data-setting="automl.metric">${['Accuracy','F1 score','Precision','Recall'].map(v=>`<option ${state.automl.metric===v?'selected':''}>${v}</option>`).join('')}</select></div><div class="field"><label>Validation strategy</label><select class="field-select" data-setting="automl.validation">${['Stratified 5-fold','Stratified 3-fold','Holdout 20%'].map(v=>`<option ${state.automl.validation===v?'selected':''}>${v}</option>`).join('')}</select></div><div class="field full"><label>Search space</label><div class="check-grid"><span class="check-chip">${state.automl.mode==='Controlled'?'Random Forest + Extra Trees':'Backend-selected broad estimator search'}</span></div></div></div><div style="display:flex;justify-content:flex-end;margin-top:18px"><button class="btn btn-violet" data-action="run-automl" ${state.automlRunning?'disabled':''}>${state.automlRunning?icon('clock',14):icon('spark',14)} ${state.automlRunning?'Searching…':'Launch AutoML'}</button></div></section><aside><section class="panel panel-accent violet"><div class="panel-header"><div><h2 class="panel-title">Best estimator</h2><p class="panel-subtitle">Selected by FLAML</p></div><span class="tag violet">${state.automlRunning?'RUNNING':'REAL RESULT'}</span></div>${state.automlRunning?'<div class="loading-state">Searching candidates and validating holdout…</div>':latestAutoHtml()}</section><section class="section-block panel"><div class="panel-header"><div><h2 class="panel-title">How to read this</h2><p class="panel-subtitle">Search constraints are persisted</p></div>${icon('info',15)}</div><p style="margin:0;color:var(--muted);font-size:11px;line-height:1.7">Controlled mode searches the selected baseline family within the seconds budget. Extended mode delegates estimator selection to a broader FLAML search space.</p></section></aside></div>`; }
function latestAutoHtml() { const e=datasetExperiments().find(item=>item.model_type.startsWith('AutoML')); return e?`<div style="display:flex;align-items:center;gap:12px;padding:13px;border:1px solid rgba(139,92,246,.28);border-radius:9px;background:var(--violet-soft)"><span class="feature-icon" style="color:#d6c9ff;background:rgba(139,92,246,.23)">${icon('spark',16)}</span><div><strong style="display:block;font-size:15px">${esc(e.model_type)}</strong><span style="display:block;margin-top:3px;color:#c5b4fc;font-family:var(--mono);font-size:9px">F1 ${pct(e.metrics.f1)} · ${e.duration_ms}ms</span></div></div>`:empty('Awaiting search','Launch FLAML to persist a real winning estimator.'); }
function chartPanel(id, title, subtitle, body='') { const runs=selectedExperiments().length?selectedExperiments():datasetExperiments(); return `<section class="panel chart-panel">${id==='comparison-metrics-chart'?comparisonWarning(runs):''}<div class="panel-header"><div><h2 class="panel-title">${title}</h2><p class="panel-subtitle">${subtitle}</p></div></div>${body}<div id="${id}" class="chart-holder"></div></section>`; }
function compareTab() { const exps=datasetExperiments(); const selected=selectedExperiments(); const chartRuns=selected.length?selected:exps; return `<div class="workspace-grid"><aside><section class="panel"><div class="panel-header"><div><span class="section-kicker">05 / compare</span><h2 class="panel-title" style="margin-top:8px">Select experiments</h2><p class="panel-subtitle">Choose persisted runs to compare.</p></div><span class="tag blue">${selected.length} SELECTED</span></div><div class="selection-list">${exps.map(e=>`<label class="selection-card ${state.selectedComparison.includes(e.id)?'selected':''}"><input type="checkbox" data-comparison="${e.id}" ${state.selectedComparison.includes(e.id)?'checked':''}/><div><strong>${esc(e.model_type)}</strong><span>${pct(e.metrics?.accuracy)} accuracy · ${Number.isFinite(Number(e.duration_ms))?`${e.duration_ms}ms`:'duration unavailable'}</span></div></label>`).join('') || empty('No experiments yet','Train a model first.')}</div></section></aside><div class="analytics-stack">${chartPanel('comparison-metrics-chart','Grouped holdout metrics','Accuracy, precision, recall, and F1 from persisted runs.')}${chartPanel('comparison-duration-chart','Quality vs duration','Each point is a persisted run; hover for model and metrics.')}${chartPanel('comparison-class-chart','Per-class quality','Classification report values for the selected runs.')}${chartPanel('comparison-confusion-chart','Confusion matrix',`<span>Counts from the selected run</span><span class="chart-mode-toggle"><button class="btn btn-ghost btn-sm ${state.comparisonMode==='raw'?'active':''}" data-action="set-confusion-mode" data-mode="raw">Raw</button><button class="btn btn-ghost btn-sm ${state.comparisonMode==='normalized'?'active':''}" data-action="set-confusion-mode" data-mode="normalized">Normalized</button></span>`)}</div></div>`; }
function explainTab() { const e=datasetExperiments()[0]; if(!e) return `<section class="panel">${empty('No explainability yet','Train a model to calculate feature importance and prediction analysis.')}</section>`; const samples=e.explainability?.sample_predictions||[]; const selectedSample=samples.find(row=>row.id===state.selectedSampleId)||samples[0]; if(selectedSample && state.selectedSampleId!==selectedSample.id) state.selectedSampleId=selectedSample.id; return `<div class="workspace-grid"><div class="analytics-stack">${chartPanel('importance-chart','Native vs permutation importance',`${esc(e.model_type)} · top transformed features from the persisted explanation.`)}${chartPanel('confidence-chart','Confidence and error analysis','Correct and incorrect holdout predictions grouped by confidence.')}<section class="panel"><div class="panel-header"><div><h2 class="panel-title">Individual sample</h2><p class="panel-subtitle">Inspect a persisted holdout prediction and its feature values.</p></div></div>${samples.length?`<select class="field-select sample-select" data-setting="explain.sample">${samples.map(row=>`<option value="${esc(row.id)}" ${row.id===selectedSample.id?'selected':''}>${esc(row.id)} · ${row.correct===false?'error':'correct'}</option>`).join('')}</select><div class="sample-detail"><div class="metric-row"><div class="mini-metric"><span>Predicted</span><b>${esc(selectedSample.predicted)}</b></div><div class="mini-metric"><span>Actual</span><b>${esc(selectedSample.actual)}</b></div><div class="mini-metric"><span>Confidence</span><b>${selectedSample.max_probability==null?'—':pct(selectedSample.max_probability)}</b></div><div class="mini-metric"><span>Outcome</span><b>${selectedSample.correct===false?'Error':'Correct'}</b></div></div><div class="sample-values">${Object.entries(selectedSample.values||{}).map(([key,value])=>`<div class="stat-row"><span>${esc(key)}</span><b>${esc(value)}</b></div>`).join('')||'<span class="panel-subtitle">No feature values were persisted for this sample.</span>'}</div></div>`:empty('No samples','The model returned no sample predictions.')}</section></div><aside><section class="panel panel-accent"><div class="panel-header"><div><h2 class="panel-title">Prediction summary</h2><p class="panel-subtitle">High-confidence errors are surfaced from the holdout set.</p></div><span class="tag blue">PERSISTED</span></div>${(e.explainability?.prediction_analysis?.high_confidence_errors||[]).length?e.explainability.prediction_analysis.high_confidence_errors.slice(0,8).map(row=>`<div class="activity-row"><span class="activity-icon">${icon('info',14)}</span><div><strong>${esc(row.id)} · ${esc(row.predicted)}</strong><span>actual ${esc(row.actual)}</span></div><span class="activity-time">${pct(row.max_probability)}</span></div>`).join(''):empty('No high-confidence errors','The persisted prediction analysis contains none.')}</section><section class="section-block panel"><div class="panel-header"><div><h2 class="panel-title">Estimator trace</h2><p class="panel-subtitle">Stored explanation boundary</p></div></div><pre style="white-space:pre-wrap;color:var(--muted);font-family:var(--mono);font-size:9px;line-height:1.65;max-height:240px;overflow:auto">${esc(e.explainability?.tree_text || 'No estimator trace was persisted.')}</pre></section></aside></div>`; }
function historyTab() { const exps=datasetExperiments(); return `<section class="panel"><div class="panel-header"><div><span class="section-kicker">07 / trace</span><h2 class="panel-title" style="margin-top:8px">Experiment History</h2><p class="panel-subtitle">Persisted runs associated with ${esc(selectedDataset()?.name || '')}</p></div></div><div class="history-table"><table><thead><tr><th>Experiment</th><th>Model</th><th>Accuracy</th><th>F1</th><th>Duration</th><th>Date</th><th>Status</th></tr></thead><tbody>${exps.length?exps.map(e=>`<tr><td><strong style="display:block;color:var(--text-soft);font-size:10px">${esc(e.model_type)}</strong><span style="display:block;margin-top:3px;color:var(--muted);font-size:9px">version ${esc(e.dataset_version_id.slice(0,8))}</span></td><td>${esc(e.model_type)}</td><td class="mono">${pct(e.metrics.accuracy)}</td><td class="mono">${pct(e.metrics.f1)}</td><td class="mono">${e.duration_ms}ms</td><td>${e.created_at?new Date(e.created_at).toLocaleString():''}</td><td><span class="status status-success"><span class="dot"></span>${esc(e.status)}</span></td></tr>`).join(''):`<tr><td colspan="7">${empty('No experiment history yet','Run a model or AutoML search to create a persisted record.')}</td></tr>`}</tbody></table></div></section>`; }
const plotLayout = (title, extra={}) => ({ paper_bgcolor:'transparent', plot_bgcolor:'transparent', font:{color:'#b5c0d2',size:11}, margin:{l:52,r:18,t:12,b:48}, legend:{orientation:'h',y:1.12}, xaxis:{gridcolor:'rgba(148,163,184,.12)'}, yaxis:{gridcolor:'rgba(148,163,184,.12)'}, ...extra });
function drawPlot(id, traces, layout) { const node=document.getElementById(id); if(!node || !window.Plotly) return; if(!traces.length) { node.innerHTML=empty('No chart data','Complete a run with the required persisted fields to populate this view.'); return; } window.Plotly.newPlot(node,traces,plotLayout('',layout),{displayModeBar:false,responsive:true}); }
function reportRows(experiment) { const report=experiment?.metrics?.classification_report||{}; return Object.entries(report).filter(([key,value])=>value && typeof value==='object' && !['accuracy','macro avg','weighted avg'].includes(key)); }
function matrixFor(experiment) { const values=experiment?.metrics?.confusion_matrix; return Array.isArray(values)&&values.length?values:null; }
function renderAnalyticsCharts() {
  if(!state.user || !window.Plotly) return;
  const runs=selectedExperiments().length?selectedExperiments():datasetExperiments();
  const metricNames=['accuracy','precision','recall','f1']; const metricColors=['#38bdf8','#8b5cf6','#10b981','#f59e0b'];
  const metricTraces=metricNames.map((metric,index)=>{ const values=runs.map(e=>Number(e.metrics?.[metric])); return {type:'bar',name:metric.toUpperCase(),x:runs.map(e=>e.model_type||'Run'),y:values,marker:{color:metricColors[index]}}; }).filter(trace=>trace.y.every(Number.isFinite));
  drawPlot('comparison-metrics-chart',metricTraces,{barmode:'group',yaxis:{range:[0,1],title:'score'},xaxis:{title:'experiment'}});
  drawPlot('comparison-duration-chart',runs.filter(e=>Number.isFinite(Number(e.duration_ms))&&Number.isFinite(Number(e.metrics?.f1))).map(e=>({type:'scatter',mode:'markers',name:e.model_type,x:[Number(e.duration_ms)],y:[Number(e.metrics.f1)],text:[`${e.model_type} · F1 ${pct(e.metrics.f1)}`],hovertemplate:'%{text}<br>Duration: %{x} ms<extra></extra>',marker:{size:11,color:'#38bdf8'}})),{xaxis:{title:'duration (ms)'},yaxis:{title:'F1 score',range:[0,1]}});
  const reportRuns=runs.filter(e=>reportRows(e).length); const classes=[...new Set(reportRuns.flatMap(e=>reportRows(e).map(([key])=>key)))]; const classScores=classes.map(key=>reportRuns.map(e=>{const row=reportRows(e).find(([name])=>name===key)?.[1]; return Number(row?.['f1-score']);})); drawPlot('comparison-class-chart',classScores.length?[{type:'heatmap',z:classScores,x:reportRuns.map(e=>e.model_type),y:classes,colorscale:'Viridis',zmin:0,zmax:1,text:classScores.map(row=>row.map(value=>Number.isFinite(value)?value.toFixed(2):'—')),texttemplate:'%{text}',hovertemplate:'Class %{y}<br>Run %{x}<br>F1 %{z:.3f}<extra></extra>'}]:[],{xaxis:{title:'experiment'},yaxis:{title:'class',autorange:'reversed'},margin:{l:110,b:60}});
  const confusion=runs.find(matrixFor), labels=confusion?.metrics?.labels||[]; let matrix=matrixFor(confusion); if(matrix&&state.comparisonMode==='normalized') matrix=matrix.map(row=>{const total=row.reduce((sum,value)=>sum+Number(value||0),0);return row.map(value=>total?Number(value)/total:0);}); drawPlot('comparison-confusion-chart',matrix&&labels.length?[{type:'heatmap',z:matrix,x:labels,y:labels,colorscale:'Blues',text:matrix.map(row=>row.map(value=>state.comparisonMode==='normalized'?`${(Number(value)*100).toFixed(1)}%`:String(value))),texttemplate:'%{text}',hovertemplate:'Actual %{y}<br>Predicted %{x}<br>%{text}<extra></extra>'}]:[],{xaxis:{title:'predicted'},yaxis:{title:'actual',autorange:'reversed'},margin:{l:70,b:60}});
  const latest=datasetExperiments()[0], imp=latest?.explainability?.feature_importance||[], perm=latest?.explainability?.permutation_importance||[], features=[...new Set([...imp,...perm].map(item=>item.feature))].slice(0,15); const importanceTraces=features.length?[{type:'bar',name:'Native',y:features,x:features.map(feature=>Number(imp.find(item=>item.feature===feature)?.importance)).map(value=>Number.isFinite(value)?value:0),orientation:'h',marker:{color:'#10b981'}},{type:'bar',name:'Permutation',y:features,x:features.map(feature=>Number(perm.find(item=>item.feature===feature)?.importance)).map(value=>Number.isFinite(value)?value:0),orientation:'h',marker:{color:'#8b5cf6'}}]:[]; drawPlot('importance-chart',importanceTraces,{barmode:'group',xaxis:{title:'importance'},yaxis:{autorange:'reversed'},margin:{l:130,r:18,t:12,b:48}});
  const analysis=latest?.explainability?.prediction_analysis; const edges=analysis?.bin_edges||[], correct=analysis?.correct||[], incorrect=analysis?.incorrect||[]; drawPlot('confidence-chart',edges.length?[{type:'bar',name:'Correct',x:edges.map(value=>`${Math.round(Number(value)*100)}%`),y:correct,marker:{color:'#10b981'}},{type:'bar',name:'Incorrect',x:edges.map(value=>`${Math.round(Number(value)*100)}%`),y:incorrect,marker:{color:'#f87171'}}]:[],{barmode:'stack',xaxis:{title:'confidence bucket'},yaxis:{title:'samples',dtick:1}});
}
function metricBars(items) { if(!items?.length) return empty('No metrics yet','Results will appear here after a completed run.'); return `<div class="metric-bars">${items.map(item=>`<div class="metric-bar-row"><div><span>${esc(item.label)}</span><b>${item.suffix || pct(item.value)}</b></div><div class="metric-bar-track"><div class="metric-bar-fill ${item.color||'cyan'}" style="width:${Math.max(2,Math.min(100,Number(item.value||0)*100))}%"></div></div></div>`).join('')}</div>`; }
function empty(title, message) { return `<div class="empty-state" style="padding:28px 10px"><span class="feature-icon">${icon('info',17)}</span><h3>${esc(title)}</h3><p>${esc(message)}</p></div>`; }

function renderModal() {
  if (state.modal === 'auth') modalRoot.innerHTML = `<div class="modal-backdrop" data-action="close-modal"><section class="modal" role="dialog" aria-modal="true"><div class="modal-header"><div><h2>${state.authMode==='login'?'Log in to TreeLab':'Create your TreeLab account'}</h2><p>${state.authMode==='login'?'Open your private ML workspace.':'Your first registered account becomes the workspace admin.'}</p></div><button class="icon-btn" data-action="close-modal">${icon('close',16)}</button></div><form id="auth-form"><div class="modal-body"><div class="field"><label>Email</label><input class="field-select" name="email" type="email" required autocomplete="email"/></div>${state.authMode==='register'?`<div class="field"><label>Name</label><input class="field-select" name="name" required minlength="2"/></div>`:''}<div class="field"><label>Password</label><input class="field-select" name="password" type="password" required minlength="8" autocomplete="${state.authMode==='login'?'current-password':'new-password'}"/></div></div><div class="modal-footer"><button type="button" class="btn btn-ghost btn-sm" data-action="toggle-auth">${state.authMode==='login'?'Need an account':'Already registered?'}</button><button class="btn btn-primary btn-sm" type="submit">${state.authMode==='login'?'Log in':'Create account'} ${icon('arrow',12)}</button></div></form></section></div>`;
  if (state.modal === 'upload') modalRoot.innerHTML = `<div class="modal-backdrop" data-action="close-modal"><section class="modal" role="dialog" aria-modal="true"><div class="modal-header"><div><h2>${state.uploadVersion?'Upload a new version':'Upload a dataset'}</h2><p>CSV parsing, validation, schema inference, and persistence run on the backend.</p></div><button class="icon-btn" data-action="close-modal">${icon('close',16)}</button></div><form id="upload-form"><div class="modal-body">${state.uploadVersion?'':`<div class="field"><label>Dataset name</label><input class="field-select" name="name" required placeholder="Customer Churn Q4"/></div><div class="field"><label>Description</label><textarea class="field-select" name="description" rows="3" placeholder="What does this dataset represent?"></textarea></div>`}<div class="dropzone"><span class="feature-icon">${icon('upload',18)}</span><strong>Choose a CSV to upload</strong><p>It will become a persisted dataset version.</p><input class="field-select" name="file" type="file" accept=".csv,text/csv" required/></div></div><div class="modal-footer"><button type="button" class="btn btn-ghost btn-sm" data-action="close-modal">Cancel</button><button class="btn btn-primary btn-sm" type="submit">Upload and profile ${icon('arrow',12)}</button></div></form></section></div>`;
  if (state.modal === 'edit') { const d=selectedDataset(); modalRoot.innerHTML = `<div class="modal-backdrop" data-action="close-modal"><section class="modal" role="dialog" aria-modal="true"><div class="modal-header"><div><h2>Edit dataset</h2><p>Metadata changes are scoped to your workspace.</p></div><button class="icon-btn" data-action="close-modal">${icon('close',16)}</button></div><form id="edit-form"><div class="modal-body"><div class="field"><label>Name</label><input class="field-select" name="name" value="${esc(d.name)}" required/></div><div class="field"><label>Description</label><textarea class="field-select" name="description" rows="3">${esc(d.description)}</textarea></div><div class="field"><label>Target column</label><select class="field-select" name="target_column">${(state.preview?.columns||d.columns||[]).map(c=>`<option ${d.target_column===c.name?'selected':''}>${esc(c.name)}</option>`).join('')}</select></div></div><div class="modal-footer"><button type="button" class="btn btn-ghost btn-sm" data-action="close-modal">Cancel</button><button class="btn btn-primary btn-sm" type="submit">Save changes ${icon('check',12)}</button></div></form></section></div>`; }
  if (state.modal === 'delete') { const d=selectedDataset(); modalRoot.innerHTML = `<div class="modal-backdrop" data-action="close-modal"><section class="modal" role="dialog" aria-modal="true"><div class="modal-header"><div><h2>Delete ${esc(d.name)}?</h2><p>The dataset will be hidden from your workspace. Its version history is retained for recovery.</p></div><button class="icon-btn" data-action="close-modal">${icon('close',16)}</button></div><div class="modal-footer"><button class="btn btn-ghost btn-sm" data-action="close-modal">Cancel</button><button class="btn btn-primary btn-sm" data-action="confirm-delete">Delete dataset ${icon('trash',12)}</button></div></section></div>`; }
}

async function handleAuth(form) { const body=Object.fromEntries(new FormData(form).entries()); state.busy=true; render(); try { state.user=await api(state.authMode==='login'?'/api/auth/login':'/api/auth/register',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}); state.modal=null; state.view='dashboard'; await refreshData(); notify(state.authMode==='login'?'Welcome back':'Workspace created','Your private workspace is ready.','success'); } catch(error){ notify('Authentication failed',error.message,'warning'); } finally { state.busy=false; render(); } }
async function handleUpload(form) { const data=new FormData(form); state.busy=true; render(); try { let path; if(state.uploadVersion) { path=`/api/datasets/${state.selectedDatasetId}/versions`; } else { path='/api/datasets'; } const result=await api(path,{method:'POST',body:data}); state.modal=null; state.uploadVersion=false; await refreshData(); state.selectedDatasetId=result.id; notify('Dataset persisted','CSV parsed, profiled, and saved as version '+result.version_number+'.','success'); await openWorkspace(result.id,'explorer'); } catch(error){ notify('Upload failed',error.message,'warning'); state.busy=false; render(); } }
async function trainModel() { const d=selectedDataset(); if(!d) return; state.training=true; render(); const cfg=state.modelType==='Decision Tree'?state.modelConfig:state.rfConfig; const parameters={...cfg,classWeight:state.preprocessing.imbalance==='Balanced class weights'?'Balanced':'None'}; try { const experiment=await api('/api/experiments/train',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({dataset_id:d.id,model_type:state.modelType,target:state.preprocessing.target,features:state.preprocessing.features,missing:state.preprocessing.missing,encoding:state.preprocessing.encoding,scaling:state.preprocessing.scaling,duplicates:state.preprocessing.duplicates,imbalance:state.preprocessing.imbalance,split:Number(state.preprocessing.split),parameters})}); state.experiments.unshift(experiment); state.selectedComparison=state.selectedComparison.length?state.selectedComparison:[experiment.id]; notify('Model trained','Real holdout metrics and explainability were persisted.','success'); } catch(error){ notify('Training failed',error.message,'warning'); } finally { state.training=false; render(); } }
async function runAutoML() { const d=selectedDataset(); if(!d) return; state.automlRunning=true; render(); try { const result=await api('/api/experiments/automl',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({dataset_id:d.id,mode:state.automl.mode,time_budget:Number(state.automl.timeBudget),metric:state.automl.metric,validation:state.automl.validation,target:state.preprocessing.target,features:state.preprocessing.features,missing:state.preprocessing.missing,encoding:state.preprocessing.encoding,scaling:state.preprocessing.scaling,duplicates:state.preprocessing.duplicates,imbalance:state.preprocessing.imbalance,split:Number(state.preprocessing.split)})}); state.experiments.unshift(result); notify('AutoML complete','FLAML selected and persisted a real estimator.','success'); } catch(error){ notify('AutoML failed',error.message,'warning'); } finally { state.automlRunning=false; render(); } }

document.addEventListener('click', async event => { const el=event.target.closest('[data-action]'); if(!el) return; const action=el.dataset.action; if(action==='close-modal' && el.classList.contains('modal-backdrop') && event.target !== el) return;
  if(action==='open-auth'){state.authMode=el.dataset.mode||'login';state.modal='auth';render();return;}
  if(action==='close-modal'){state.modal=null;state.uploadVersion=false;render();return;}
  if(action==='toggle-auth'){state.authMode=state.authMode==='login'?'register':'login';render();return;}
  if(action==='dismiss-toast'){state.toasts=state.toasts.filter(t=>t.id!==el.dataset.id);renderToasts();return;}
  if(action==='nav'){setView(el.dataset.view);return;}
  if(action==='go-home'){setView('dashboard');return;}
  if(action==='scroll-workflow'){document.getElementById('workflow')?.scrollIntoView({behavior:'smooth'});return;}
  if(action==='logout'){try{await api('/api/auth/logout',{method:'POST'});}catch{} state.user=null;state.datasets=[];state.experiments=[];state.view='landing';render();return;}
  if(action==='open-upload'){state.modal='upload';state.uploadVersion=false;render();return;}
  if(action==='open-version-upload'){state.modal='upload';state.uploadVersion=true;render();return;}
  if(action==='open-dataset'){await openWorkspace(el.dataset.id,'overview');return;}
  if(action==='edit-dataset'){state.selectedDatasetId=el.dataset.id;state.modal='edit';render();return;}
  if(action==='delete-dataset'){state.selectedDatasetId=el.dataset.id;state.modal='delete';render();return;}
  if(action==='confirm-delete'){try{await api(`/api/datasets/${state.selectedDatasetId}`,{method:'DELETE'});state.modal=null;await refreshData();state.view='datasets';notify('Dataset deleted','The dataset was removed from your active workspace.','success');render();}catch(error){notify('Delete failed',error.message,'warning');}return;}
  if(action==='workspace-tab'){if(!selectedDataset() && !['history'].includes(el.dataset.tab)){notify('Choose a dataset','Open a dataset before entering a lab.','warning');return;} if(state.view!=='workspace') await openWorkspace(state.selectedDatasetId,el.dataset.tab); else {state.workspaceTab=el.dataset.tab;render();}return;}
  if(action==='set-model'){state.modelType=el.dataset.model;render();return;}
  if(action==='set-confusion-mode'){state.comparisonMode=el.dataset.mode;render();return;}
  if(action==='set-automl-mode'){state.automl.mode=el.dataset.mode;render();return;}
  if(action==='train-model'){await trainModel();return;}
  if(action==='run-automl'){await runAutoML();return;}
});

document.addEventListener('input', event => { if(event.target.id==='dataset-search'){state.search=event.target.value;render();} });
document.addEventListener('change', event => { const el=event.target;
  if(el.dataset.feature){ if(el.checked) state.preprocessing.features.push(el.dataset.feature); else state.preprocessing.features=state.preprocessing.features.filter(v=>v!==el.dataset.feature); render(); return; }
  if(el.dataset.comparison){ if(el.checked) state.selectedComparison.push(el.dataset.comparison); else state.selectedComparison=state.selectedComparison.filter(v=>v!==el.dataset.comparison); render(); return; }
  if(el.dataset.setting==='explain.sample'){ state.selectedSampleId=el.value; render(); return; }
  const setting=el.dataset.setting; if(!setting) return; const [scope,key]=setting.split('.'); const target=scope==='preprocessing'?state.preprocessing:scope==='model'?state.modelConfig:scope==='rf'?state.rfConfig:state.automl; target[key]=el.type==='number'||el.type==='range'?Number(el.value):el.value; if(scope==='preprocessing' && key==='target') state.preprocessing.features=state.preview?.columns.map(c=>c.name).filter(c=>c!==el.value)||[]; render();
});
document.addEventListener('submit', async event => { if(event.target.id==='auth-form'){event.preventDefault();await handleAuth(event.target);} if(event.target.id==='upload-form'){event.preventDefault();await handleUpload(event.target);} if(event.target.id==='edit-form'){event.preventDefault();const body=Object.fromEntries(new FormData(event.target).entries());try{await api(`/api/datasets/${state.selectedDatasetId}`,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});state.modal=null;await refreshData();notify('Dataset updated','Metadata changes were saved.','success');render();}catch(error){notify('Update failed',error.message,'warning');}} });

(async function boot(){ await refreshHealth(); try { state.user=await api('/api/auth/me'); state.view='dashboard'; await refreshData(); } catch { state.user=null; } render(); })();
